using System.Text;

namespace Zendiator.SourceGenerator;

// C04 first candidate: one async iterator loop for the validated same-item interval.
// The facade supplies the existing public cursor protocol; no custom IValueTaskSource is written.
internal static class CanonicalStreamPrototypeEmitter
{
    internal static CanonicalSourceFile Emit(CanonicalStreamPrototypeModel model)
    {
        var h = model.Handler;
        var b = new StringBuilder();
        b.AppendLine($$"""
            // <auto-generated/>
            #nullable enable
            // Unregistered Stream candidate. Public canonical runtime acceptance remains blocked.
            namespace {{model.Namespace}}
            {
                internal static class {{model.ClassName}}{{model.Generic?.TypeParameters}}{{model.Generic?.TypeConstraints}}
                {
                    internal static global::System.Collections.Generic.IAsyncEnumerable<{{h.ItemName}}> Create(
                        global::System.IServiceProvider services, {{h.RequestName}} request,
                        global::System.Threading.CancellationToken token = default)
                    {
                        global::System.ArgumentNullException.ThrowIfNull(services);
                        global::System.ArgumentNullException.ThrowIfNull(request);
                        return new Envelope(services, request, token);
                    }
                    private sealed class Envelope(global::System.IServiceProvider services, {{h.RequestName}} request,
                        global::System.Threading.CancellationToken api) : global::System.Collections.Generic.IAsyncEnumerable<{{h.ItemName}}>
                    {
                        public global::System.Collections.Generic.IAsyncEnumerator<{{h.ItemName}}> GetAsyncEnumerator(
                            global::System.Threading.CancellationToken enumeration = default) => new Cursor(services, request, api, enumeration);
                    }
                    private sealed class Cursor(global::System.IServiceProvider services, {{h.RequestName}} request,
                        global::System.Threading.CancellationToken api, global::System.Threading.CancellationToken enumeration)
                        : global::System.Collections.Generic.IAsyncEnumerator<{{h.ItemName}}>
                    {
                        private global::System.Collections.Generic.IAsyncEnumerator<{{h.ItemName}}>? _inner;
                        private global::System.Threading.CancellationTokenSource? _linked;
                        private global::System.Threading.CancellationToken _token;
                        private bool _ended, _disposed, _hasCurrent;
                        private int _busy;
                        private {{h.ItemName}} _current = default!;
                        public {{h.ItemName}} Current => _hasCurrent ? _current : throw new global::System.InvalidOperationException("Current is unavailable.");
                        private void Enter()
                        {
                            if (global::System.Threading.Interlocked.CompareExchange(ref _busy, 1, 0) != 0)
                                throw new global::System.InvalidOperationException("Await the preceding operation.");
                        }
                        public global::System.Threading.Tasks.ValueTask<bool> MoveNextAsync()
                        {
                            Enter(); _hasCurrent = false;
                            if (_ended || _disposed) { global::System.Threading.Volatile.Write(ref _busy, 0); return new(false); }
                            return Move();
                        }
                        private async global::System.Threading.Tasks.ValueTask<bool> Move()
                        {
                            try
                            {
                                if (_inner is null)
                                {
                                    _token = !api.CanBeCanceled ? enumeration : !enumeration.CanBeCanceled || api == enumeration ? api
                                        : (_linked = global::System.Threading.CancellationTokenSource.CreateLinkedTokenSource(api, enumeration)).Token;
                                    _token.ThrowIfCancellationRequested();
                                    _inner = RunSegment(services, request, _token).GetAsyncEnumerator();
                                }
                                _token.ThrowIfCancellationRequested();
                                if (await _inner.MoveNextAsync().ConfigureAwait(false))
                                { _current = _inner.Current; _hasCurrent = true; return true; }
                                _ended = true; await Close().ConfigureAwait(false); return false;
                            }
                            catch { _ended = true; await Close().ConfigureAwait(false); throw; }
                            finally { global::System.Threading.Volatile.Write(ref _busy, 0); }
                        }
                        public global::System.Threading.Tasks.ValueTask DisposeAsync()
                        {
                            Enter(); _hasCurrent = false;
                            if (_disposed) { global::System.Threading.Volatile.Write(ref _busy, 0); return default; }
                            _disposed = _ended = true; return Dispose();
                        }
                        private async global::System.Threading.Tasks.ValueTask Dispose()
                        {
                            try { await Close().ConfigureAwait(false); }
                            finally { global::System.Threading.Volatile.Write(ref _busy, 0); }
                        }
                        private async global::System.Threading.Tasks.ValueTask Close()
                        {
                            var inner = _inner; var linked = _linked; _inner = null; _linked = null;
                            try { if (inner is not null) await inner.DisposeAsync().ConfigureAwait(false); }
                            finally { linked?.Dispose(); }
                        }
                    }
                    private static async global::System.Collections.Generic.IAsyncEnumerable<{{h.ItemName}}> RunSegment(
                        global::System.IServiceProvider services, {{h.RequestName}} request,
                        [global::System.Runtime.CompilerServices.EnumeratorCancellation] global::System.Threading.CancellationToken token)
                    {
            """);
        for (var i = 0; i < model.Hooks.Count; i++)
            b.AppendLine("            " + model.Hooks[i].ContractName + "? hook" + i + " = null;");
        b.AppendLine($$"""
                        global::System.Collections.Generic.IAsyncEnumerator<{{h.ItemName}}>? source = null;
                        try
                        {
                            token.ThrowIfCancellationRequested();
                            var handler = ({{h.ContractName}})global::Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.GetRequiredService(services, typeof({{h.HandlerName}}));
                            source = handler.{{h.MethodName}}(request, token).GetAsyncEnumerator(token);
                            while (true)
                            {
            """);
        foreach (var site in model.ItemRegion.Steps)
        {
            switch (site.Id.Phase)
            {
                case StreamPhase.SourceGuard:
                case StreamPhase.HookGuard:
                    b.AppendLine("                    token.ThrowIfCancellationRequested();"); break;
                case StreamPhase.SourceMove:
                    b.AppendLine("                    if (!await source.MoveNextAsync().ConfigureAwait(" +
                        (model.ItemRegion.MoveAwait.ConfigureAwaitFalse ? "false" : "true") + ")) yield break;"); break;
                case StreamPhase.SourceCurrent:
                    b.AppendLine("                    var " + Slot(model.ItemRegion.CurrentTransfer.Destination) + " = " +
                        Slot(model.ItemRegion.CurrentTransfer.Source) + ";"); break;
                case StreamPhase.ResolveHook:
                    var service = model.Hooks[site.Id.Stage];
                    b.AppendLine("                    hook" + site.Id.Stage + " ??= (" + service.ContractName + ")global::Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.GetRequiredService(services, typeof(" + service.HookName + "));"); break;
                case StreamPhase.Filter:
                case StreamPhase.Map:
                    var callback = model.Hooks[site.Id.Stage];
                    var call = "hook" + site.Id.Stage + "." + callback.MethodName + "(request, item, token)";
                    b.AppendLine(site.Id.Phase == StreamPhase.Filter ? "                    if (!" + call + ") continue;" : "                    item = " + call + ";"); break;
                case StreamPhase.CacheCurrent:
                    b.AppendLine("                    yield return item;"); break;
                default:
                    throw new System.InvalidOperationException("Unsupported lowered Stream item site.");
            }
        }
        b.AppendLine("                }");
        b.AppendLine("            }");
        b.AppendLine("            finally");
        b.AppendLine("            {");
        foreach (var site in model.CleanupRegion.Steps)
        {
            switch (site.Id.Phase)
            {
                case StreamPhase.DetachSource:
                    b.AppendLine("                var " + Slot(model.CleanupRegion.DetachTransfer.Destination) + " = " +
                        Slot(model.CleanupRegion.DetachTransfer.Source) + "; " + Slot(model.CleanupRegion.DetachTransfer.Source) + " = null;"); break;
                case StreamPhase.SourcePresent:
                    b.AppendLine("                if (" + Slot(model.CleanupRegion.DetachTransfer.Destination) + " is not null)"); break;
                case StreamPhase.DisposeSource:
                    b.AppendLine("                    await " + Slot(model.CleanupRegion.DetachTransfer.Destination) + ".DisposeAsync().ConfigureAwait(" +
                        (model.CleanupRegion.DisposeAwait.ConfigureAwaitFalse ? "false" : "true") + ");"); break;
                default:
                    throw new System.InvalidOperationException("Unsupported lowered Stream source cleanup site.");
            }
        }
        b.AppendLine("            }");
        b.AppendLine("        }");
        b.AppendLine("    }");
        b.AppendLine("}");
        return new(model.HintName, b.ToString());
    }

    private static string Slot(string value) => value switch
    {
        "source/Current" => "source.Current",
        "cursor/item" => "item",
        "cursor/source" => "source",
        "dispose/source" => "detached",
        _ => throw new System.InvalidOperationException("Unsupported lowered Stream operand.")
    };
}
